import java.util.*;

class Solution {
  public List<String> wordsAbbreviation(List<String> words) {
    int n = words.size();
    String[] abbr = new String[n];
    int[] prefix = new int[n];
    for (int i = 0; i < n; i++) {
      prefix[i] = 1;
      abbr[i] = abbreviate(words.get(i), 1);
    }
    // keep lengthening the prefix of every word whose abbreviation collides
    for (boolean changed = true; changed; ) {
      changed = false;
      Map<String, List<Integer>> groups = new HashMap<>();
      for (int i = 0; i < n; i++) groups.computeIfAbsent(abbr[i], k -> new ArrayList<>()).add(i);
      for (List<Integer> g : groups.values()) {
        if (g.size() < 2) continue;
        changed = true;
        for (int i : g) abbr[i] = abbreviate(words.get(i), ++prefix[i]);
      }
    }
    return Arrays.asList(abbr);
  }

  private String abbreviate(String w, int k) {
    if (k + 2 >= w.length()) return w; // would not be shorter
    return w.substring(0, k) + (w.length() - k - 1) + w.charAt(w.length() - 1);
  }
}
